#include "stdafx.h"#include "LocalUtils.h"#include <rsuNoNames.h>#include <macros/StrHelps.h>#include <UtilsH.h>#include <UtilsSM.h>#include <UtilsQB.h>extern KNoName g_Objs, g_IOs, g_IOsObjsInfo, g_smIOs, g_qbIOs;static KNoName* pNoNames[] = { &g_Objs, &g_IOs, &g_qbIOs, &g_smIOs };CBase* _FindConnPoint( LPCSTR ObjName, DWORD TypeID, int number ){  CBase* pB = NULL;  for( int i=0; i<_countof(pNoNames); ++i )  {    pB = pNoNames[i]->FindStruct( ObjName, TypeID, number );    if( pB )      break;  }  return pB;}bool _GetNameEx( CBase* pB, LPCSTR* pszClass, LPCSTR* pszEntry, int *pFcsNumber ){  for( int i=0; i<_countof(pNoNames); ++i )  {    if( pNoNames[i]->GetNameEx( pB->ID_PNT_NAME, pB->ID_CLASS, pszClass, pszEntry, pFcsNumber ) )      return true;  }  return false;}#include "QB_UserDefName.h"DWORD _FindHoney( KNoName &noContainer, LPSTR pszNameIn, DWORD type, BYTE **buffer, int &sizeReq, tMemReallocer pMemR, DWORD &nPoints ){  LPSTR p = &pszNameIn[strlen(pszNameIn)];  bool bF = false;  nPoints = 0;  SValueDef localVD;  while( p )  {    TStringTerminator st( p );    const char* pszName;    DWORD ID = 0;    CBase* pBase = NULL;    int nFcs = 0;    while( noContainer.WhileBase( ID, id_Unknown, &pBase, &pszName, &nFcs ) )    {      if( !_strcmpi(pszName, pszNameIn) )      {        if( bF )        {          SValueDef* def = NameToValueH( pBase->ID_CLASS, p+1 );          if( !def )          {            def = NameToValueQB( pBase->ID_CLASS, p+1 );            if( !def )            {              if( W_QBANALOG::TypeID==pBase->ID_CLASS )              {                def = UserDefName( (W_QBANALOG*)pBase, p+1, localVD );              }              else if( W_QBSTATUS::TypeID==pBase->ID_CLASS )              {                def = UserDefName( (W_QBSTATUS*)pBase, p+1, localVD );              }              else if( W_QBPSA::TypeID==pBase->ID_CLASS )              {                def = UserDefName( (W_QBPSA*)pBase, p+1, localVD );              }            }          }          if( !def )          {            def = NameToValueSM( pBase->ID_CLASS, p+1 );            if( !def && IsSMAcy(pBase->ID_CLASS) )            {              if( !strcmp(p+1, "OPFL") )                def = NameToValueSM( pBase->ID_CLASS, "PVFL" );              else if( !strcmp(p+1, "PV") )                def = NameToValueSM( pBase->ID_CLASS, "PVFL" );            }          }          if( !def )            continue;        }        const size_t lenName = strlen(pszName)+1;        size_t nBytes = sizeof(pBase->ID_CLASS) + lenName;        if( bF )          nBytes += strlen(p+1);        nBytes += 1;        // Используем в качестве выходного буфера - входной        BYTE* pMemOut = *buffer = pMemR( *buffer, (int)nBytes, sizeReq );        CopyMemory( pMemOut, &pBase->ID_CLASS, sizeof(pBase->ID_CLASS) );        pMemOut += sizeof(pBase->ID_CLASS);        CopyMemory( pMemOut, pszName, lenName );        pMemOut += lenName;        if( bF )        {          ++p;           CopyMemory( pMemOut, p, strlen(p)+1 );        }        else          CopyMemory( pMemOut, "", 1 );        return (DWORD)nBytes;      }    }    if( !type )      break;    bF = true;    p = strrchr( pszNameIn, '.' );    ++nPoints;  }  return 0;}DWORD _FindHoney2( LPSTR pszNameIn, DWORD type, BYTE **buffer, int &sizeReq, tMemReallocer pMemR ){  LPSTR p = &pszNameIn[strlen(pszNameIn)];  bool bF = false;  while( p )  {    TStringTerminator st( p );    SPntTypeInfo *pInfo = (SPntTypeInfo*)g_IOsObjsInfo.FindStruct( pszNameIn, id_PntTypeInfo, 0 );    if( pInfo )    {      CBase* pBase = NULL;      switch( pInfo->nObjOrIO )      {      case SPntTypeInfo::entObj:        pBase = g_Objs.FindStruct( pszNameIn, pInfo->realTypeID, 0 );        break;      case SPntTypeInfo::entIO:        pBase = g_IOs.FindStruct( pszNameIn, pInfo->realTypeID, 0 );        break;      }      if( !pBase )      {        bF = true;        p = strrchr( pszNameIn, '.' );        continue;      }      if( bF )      {        SValueDef* def = NameToValueH( pBase->ID_CLASS, p+1 );        if( !def )        {          bF = true;          p = strrchr( pszNameIn, '.' );          continue;        }      }      const size_t lenName = strlen(pszNameIn)+1;      size_t nBytes = sizeof(pBase->ID_CLASS) + lenName;      if( bF )        nBytes += strlen(p+1);      nBytes += 1;      // Используем в качестве выходного буфера - входной      BYTE* pMemOut = *buffer = pMemR( *buffer, (int)nBytes, sizeReq );      CopyMemory( pMemOut, &pBase->ID_CLASS, sizeof(pBase->ID_CLASS) );      pMemOut += sizeof(pBase->ID_CLASS);      CopyMemory( pMemOut, pszNameIn, lenName );      pMemOut += lenName;      if( bF )      {        ++p;         CopyMemory( pMemOut, p, strlen(p)+1 );      }      else        CopyMemory( pMemOut, "", 1 );      return (DWORD)nBytes;    }    bF = true;    p = strrchr( pszNameIn, '.' );  }  return 0;}DWORD _FindHoney( DWORD qRsuNumber, LPSTR pszNameIn, DWORD type, BYTE **buffer, int &sizeReq, tMemReallocer pMemR ){  char localBuf[128];  strcpy_s( localBuf, pszNameIn );  DWORD test = _FindHoney2( localBuf, type, buffer, sizeReq, pMemR );  if( test )  {    return test;  }  strcpy_s( localBuf, pszNameIn );  DWORD nPoints[4] = {};  DWORD ress[4] = {};  ASS( _countof(pNoNames)==_countof(nPoints) );    int p = -1;  DWORD minP = _countof(localBuf) + 10;  int nRess = 0;  for( int i=0; i<_countof(nPoints); ++i )  {    ress[i] = _FindHoney( *pNoNames[i], localBuf, type, buffer, sizeReq, pMemR, nPoints[i] );    if( !ress[i] )      continue;    ++nRess;    if( nPoints[i]< minP )    {      minP = nPoints[i];      p = i;    }  }  if( -1==p )    return 0;  if( 1==nRess )    return ress[p];  return _FindHoney( *pNoNames[p], localBuf, type, buffer, sizeReq, pMemR, nPoints[p] );}